    }
}

void merge(int a[], int lo, int md, int hi)
{
    int i = lo, j = md + 1, k = lo;
    int b[MAXN + 3];

    while (k &lt; hi)
    {
        if (i &lt;= md &amp;&amp; j &lt;= hi)
        {
            if (a[i] &lt;= a[j])
                b[k++] = a[i++];
            else
                b[k++] = a[j++];
        }
        else
            break;
    }

    while (i &lt;= md)
        b[k++] = a[i++];
    while (j &lt;= hi)
        b[k++] = a[j++];

    for (k = lo; k &lt;= hi; k++)
        a[k] = b[k];
}
</code></pre> 快速排序：Lomuto <pre><code>void quicksort_lomuto(int a[], int low, int high)
{
    int pivot;
    if(low&lt;high)
    {
        pivot=partition(a, low, high);
        quicksort_lomuto(a, low, pivot-1);
        quicksort_lomuto(a, pivot+1, high);
    }
}

int partition(int a[], int low, int high)
{
    int pi=a[high];
    int i=low;
    for(int j=low;j&lt;=high;j++)
    {
        if(a[j]&lt;pi)
        {
            int t=a[i];
            a[i]=a[j];
            a[j]=t;
            i++;
        }
    }
    int k=a[i];
    a[i]=a[high];
    a[high]=k;

    return i;
}
</code></pre> 快速排序：Hoare <pre><code>void quicksort_hoare(int a[], int low, int high)
{
    int pivot;
    if(low&lt;high)
    {
        pivot=partition(a, low, high);
        quicksort_hoare(a, low, pivot-1);
        quicksort_hoare(a, pivot+1, high);
    }
}

int partition(int a[], int low, int high)
{
    int pi=a[low+(high-low)/2];
    int i=low-1;
    int j=high+1;
    while(1)
    {
        do{
            i++;
        }while(a[i]&lt;pi);
        do{
            j--;
        }while(a[j]&gt;pi);

        if(i&lt;=j)
            return j;
        int t=a[i];
        a[i]=a[j];
        a[j]=t;
    }
}
</code></pre> qsort 用法 <pre><code>#include &lt;stdlib.h&gt;
