单链表 <pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

typedef struct _node
{
    int value;
    struct _node *next;
} Node;

typedef struct
{
    Node *head;
    Node *tail;
} List;

List list_create()
{
    List list = {NULL, NULL};
    return list;
}

void list_free(List *list)
{
    for(Node *p=list-&gt;head;p;)
    {
        Node *q=p-&gt;next;
        free(p);
        p=q;
    }
    list-&gt;head=list-&gt;tail=NULL;
}

void list_append(List *list, int v)
{
    Node *p = (Node *)malloc(sizeof(Node));
    p-&gt;value = v;
    p-&gt;next = NULL;
    if (list-&gt;tail)
    {
        list-&gt;tail-&gt;next = p;
        list-&gt;tail = p;
    }
    else
    {
        list-&gt;head = list-&gt;tail = p;
    }
}

void list_insert(List *list, int v)
{
    Node *p = (Node *)malloc(sizeof(Node));
    p-&gt;value = v;
    p-&gt;next = list-&gt;head;
    list-&gt;head = p;
    if (list-&gt;tail == NULL)
    {
        list-&gt;tail = p;
    }
}

int list_find(List *list, int v)
{
    int cnt = 0;
    Node *p = list-&gt;head;
    while (p)
    {
        if (p-&gt;value == v)
        {
            return cnt;
        }
        cnt++;
        p = p-&gt;next;
    }
    return -1;
}

void list_remove(List *list, int v)
{
    for (Node *p = list-&gt;head, *q = NULL; p;)
    {
        if (p-&gt;value == v)
        {
            Node *r = p-&gt;next;
            if (q)
            {
                q-&gt;next = p-&gt;next;
            }
            else
            {
                list-&gt;head = p-&gt;next;
            }
            if (p == list-&gt;tail)
            {
                list-&gt;tail = q;
            }
            free(p);
            p = r;
        }
        else
        {
            q = p;
            p = p-&gt;next;
        }
    }
}
</code></pre> 双头双向链表 <pre><code>typedef struct _Node {
    int value;
    struct _Node *next;
    struct _Node *prev;
} Node;

typedef struct {
    Node *head;
    Node *tail;
} List;

void list_print(List *list)
{
    for ( Node *p = list-&gt;head; p; p=p-&gt;next ) {
        printf("%d ", p-&gt;value);
    }
    printf("\n");
}

void list_clear(List *list)
{
    for ( Node *p = list-&gt;head, *q; p; p=q ) {
        q = p-&gt;next;
        free(p);
    }
}

void list_append(List *list, int value)
{
    Node *p = (Node *)malloc(sizeof(Node));
    p-&gt;value = value;
    if (list-&gt;tail)
    {
        p-&gt;prev = list-&gt;tail;
        list-&gt;tail-&gt;next = p;
        list-&gt;tail = p;
        p-&gt;next = NULL;
    }
    else
    {
        list-&gt;tail = list-&gt;head = p;
        p-&gt;next = p-&gt;prev = NULL;
    }
}

void list_remove(List *list, int value)
{
    for (Node *p = list-&gt;head; p;)
    {
        if (p-&gt;value == value)
        {
            Node *n = p-&gt;next;
            if (p-&gt;prev)
                p-&gt;prev-&gt;next = p-&gt;next;
            else
                list-&gt;head = p-&gt;next;

            if (p-&gt;next)
                p-&gt;next-&gt;prev = p-&gt;prev;
            else
                list-&gt;tail = p-&gt;prev;

            free(p);
            p = n;
        }
        else
            p = p-&gt;next;
    }
}
</code></pre>

